import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.DoCD98hS.js";const h=JSON.parse('{"title":"qiankun 2 · 页签核心与主微应用模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/qiankun.md","filePath":"modules/catalog/qiankun.md","lastUpdated":1794981335000}'),r={name:"modules/catalog/qiankun.md"};function c(n,e,i,l,u,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="qiankun-2-·-页签核心与主微应用模板" tabindex="-1">qiankun 2 · 页签核心与主微应用模板 <a class="header-anchor" href="#qiankun-2-·-页签核心与主微应用模板" aria-label="Permalink to &quot;qiankun 2 · 页签核心与主微应用模板&quot;">​</a></h1><p>页签核心、Vue 3 适配及 Vue 2 / Vue 3 各自的主应用、app1、app2 合并介绍；同一方案的应用角色不再各拆一篇。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-qiankun-tabs-core</code></td><td>框架无关的页签身份、路由状态与微应用运行时</td></tr><tr><td><code>@melt-js/libs-qiankun-tabs-vue3</code></td><td>Vue 3 页签管理与宿主 / 子应用适配</td></tr><tr><td><code>@melt-js/libs-qiankun-tabs-vue2</code></td><td>Vue 2.7 页签管理、页签 UI、缓存与微应用保活适配（<code>Vue.use</code> 注册，不支持 2.6 及以下）</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-main</code></td><td>Vue 2 主应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-app1</code></td><td>Vue 2 微应用一</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue2-app2</code></td><td>Vue 2 微应用二</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-main</code></td><td>Vue 3 主应用</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-app1</code></td><td>Vue 3 微应用一</td></tr><tr><td><code>@melt-js/tpl-qiankun2-vue3-app2</code></td><td>Vue 3 微应用二</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>链接按各包 <code>package.json</code> 的 <code>unpkg</code> 入口生成，打开 npm 已发布的默认版本；页面内容随包发布更新。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>unpkg 演示</th></tr></thead><tbody><tr><td><code>tpl-qiankun2-vue2-main</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-main/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-qiankun2-vue2-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-app1/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-qiankun2-vue2-app2</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue2-app2/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-qiankun2-vue3-main</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-main/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-qiankun2-vue3-app1</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-app1/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-qiankun2-vue3-app2</code></td><td><a href="https://unpkg.com/@melt-js/tpl-qiankun2-vue3-app2/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr></tbody></table><p>qiankun 场景先打开对应主应用；app1 / app2 链接也用于主应用配置微应用入口。</p><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>core：<code>MicroAppRuntime</code> / <code>RouteDispatcher</code> / <code>MicroPageCache</code></td><td>运行时、路由调度与页面缓存</td></tr><tr><td>Vue 3：<code>installMicroTabsBridge</code> / <code>createMicroAppCache</code></td><td>主应用桥接与微应用缓存</td></tr><tr><td>Vue 3：<code>useTabQuery</code> / <code>createTabsUrlSync</code></td><td>页签查询状态与 URL 同步</td></tr><tr><td>Vue 2：<code>createTabsManager</code> / <code>tabsManager</code> 插件</td><td>页签管理器创建与 <code>Vue.use</code> 注册（内部完成 registerModules 与 setupPlugins）</td></tr><tr><td>Vue 2：<code>createMicroAppCache</code> / <code>useMicroAppCache</code>（<code>/child</code> 子路径）</td><td>子应用 keep-alive 缓存模型，输出 <code>state.keepAliveList</code> 与 <code>cache.key()</code></td></tr><tr><td>Vue 2：<code>createMicroTabController</code> / <code>installMicroTabsBridge</code> / <code>createTabsUrlSync</code></td><td>子应用页签控制、宿主消息桥接与 URL 同步</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>Vue 3：<code>MicroAppView</code> 与页签 UI</td><td>微应用容器与标签页，完整清单待补</td></tr><tr><td>Vue 2：<code>DynamicTabsComponent</code> / <code>DynamicContainerComponent</code></td><td>动态页签与容器组件</td></tr></tbody></table><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p>Vue 2 与 Vue 3 是两套宿主示例，各自使用对应适配包：Vue 3 用 <code>libs-qiankun-tabs-vue3</code>，Vue 2.7 用 <code>libs-qiankun-tabs-vue2</code>（通过 <code>Vue.use(tabsManager)</code> 注册，组件内由 <code>this.$tabsManager</code> 或 <code>useTabsManager()</code> 取管理器）。普通页签工具与微应用中的 hel 组件加载分别配置。Vue 2 子应用的缓存模型走 <code>/child</code> 子路径，<code>createMicroAppLifecycles()</code> 仍是 Vue 3 风格契约，Vue 2 需手写 bootstrap / mount / unmount。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>Vue 2 模板来自 qiankun-tabsCache，Vue 3 模板来自 qiankun-vue3-tabsPage。主应用负责导航与应用注册，app1 / app2 用来验证多微应用和多页签。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><p>以下先列改造顺序，具体文件、配置和代码差异在实现定稿后补齐。</p><ol><li>先按框架整理主应用注册项、微应用入口、路由 base 和构建 public path。</li><li>Vue 3 接入 tabs-core 与 tabs-vue3 的实际公开能力，建立宿主桥接与子应用缓存；Vue 2.7 接入 tabs-vue2，主应用用 <code>Vue.use(tabsManager)</code> 注册，子应用用 <code>/child</code> 的 <code>createMicroAppCache</code> 管理 keep-alive。webpack 4 不读 <code>exports</code>，需在 <code>vue.config.js</code> 里为 <code>style.css</code> 与 core 子路径配置 alias。</li><li>处理 qiankun bootstrap / mount / unmount / update 生命周期及同一微应用多页签的路由传递。</li><li>仅对需要 hel 组件的微应用增加对应运行时与加载步骤，分别验证切页、回退、刷新和卸载。</li></ol><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补 Vue 2 / Vue 3、主应用 / app1 / app2 的职责与差异表。</li><li>[ ] 补页签身份、路由状态、keep-alive 与 URL 同步 API。</li><li>[ ] 补两种上游模板的逐文件改造表、启动组合和部署路径。</li></ul>',22)])])}const b=t(r,[["render",c]]);export{h as __pageData,b as default};
